# 41e_professionalisation_pca.R
# Political professionalisation index — annual series + PCA
#
# Three components, 1979–2025:
#   1. Career politicians % (Criddle + Henn-adjusted; step function by parliament)
#   2. SPADs in post (observed + linearly interpolated)
#   3. Mean staffing spend per MP, real terms (Butler & Butler (2011)-calibrated
#      pre-2010, IPSA annual post-2011 — see 41m_staffing_calibrate_butler.R)
#
# ✅ 7 Sep 2026: pre-2010 staffing REPOINTED from the flat-85%-assumption
#   placeholder to a real, empirically-calibrated series (Butler & Butler
#   maxima x the true 2012-2016 IPSA overlap ratio). Every number below is
#   superseded relative to any report before this date.
#
# OUTPUTS:
#   figures/ch3_professionalisation_pca_talk.png

if (!require("pacman")) install.packages("pacman")
pacman::p_load(dplyr, ggplot2, readr, patchwork, tidyr, tibble)

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})  # portable project root: works via Rscript from anywhere, or falls back to
    # getwd() when sourced interactively (assumes ch3_pipeline_restored/ as cwd)
PROJECT  <- .ROOT
TALK_OUT <- file.path(PROJECT, "figures/ch3_professionalisation_pca_talk.png")

NAVY      <- "#1F3864"
RED       <- "#d7191c"
GREY_BLUE <- "#607D8B"
COL_CAR   <- "#2166ac"   # career politicians
COL_SPAD  <- "#d95f02"   # SPADs
COL_STAFF <- "#1b7837"   # staffing

YEARS <- 1979:2025

# ============================================================
# 1. CAREER POLITICIANS — step function by parliament
# ============================================================
# Confirmed Criddle values (from CSV, excluding 1974)
career_criddle <- tribble(
  ~year, ~pct,
  1979,  3.0,
  1983,  4.5,
  2010, 14.0,
  2015, 17.0,
  2019, 21.0
)

# Henn (2018) Table 6, "Politician/Pol Organiser" row — his own narrower
# category, same definition as Criddle's, reported directly by election year,
# no calibration needed. FIXED 5 Sep 2026: this tribble previously held wrong
# values (1.4/3.3/5.0/6.4/7.7 + 6.7pp calibration) that did not match Henn's
# actual Table 6 — traced during the CBP-7529/Cairney cross-check (see
# 41_career_politicians.R and build_fig_3_2_professionalisation_composite.R,
# fixed there 3-4 Sep; this script, and 41f/41g/41i/41j which copy its
# construction, were not caught until PJ asked "why not 47 obs" and a broader
# consistency check followed).
career_henn <- tribble(
  ~year, ~pct,
  1987,  5.4,
  1992,  7.3,
  1997,  9.5,
  2001,  10.5,
  2005,  14.1
)

career_obs <- bind_rows(career_criddle, career_henn) |> arrange(year)

# Step function: for each year use the most recent election-year observation
career_annual <- tibble(year = YEARS) |>
  mutate(
    obs_yr      = sapply(year, function(y)
      max(career_obs$year[career_obs$year <= y], na.rm = TRUE)),
    career_pct  = career_obs$pct[match(obs_yr, career_obs$year)],
    career_src  = if_else(obs_yr %in% career_criddle$year, "Criddle", "Henn-adjusted")
  )

cat("Career politicians series:\n")
print(career_annual |> filter(year %in% c(1979:1981, 1987:1989, 2009:2012, 2019:2021)))

# ============================================================
# 2. SPADs — linear interpolation between observations
# ============================================================
spads_data <- read_csv(file.path(PROJECT, "data/raw/spads_DATA_ENTRY.csv"),
                       show_col_types = FALSE)

# Restrict to 1979–2023 for interpolation
spads_fit <- spads_data |> filter(year <= 2025)
spads_interp <- approx(spads_fit$year, spads_fit$n_spads,
                       xout = YEARS, method = "linear", rule = 2)
spads_annual <- tibble(year = YEARS, n_spads = spads_interp$y)

cat("\nSPADs series (sample):\n")
print(spads_annual |> filter(year %in% c(1979, 1985, 1992, 2000, 2010, 2019, 2023)))

# ============================================================
# 3. STAFFING — step function pre-2010, annual post-2011
# ============================================================
ipsa <- read_csv(file.path(PROJECT, "data/processed/ipsa_staffing_annual.csv"),
                 show_col_types = FALSE) |>
  select(cal_year, staffing_real = mean_staffing_real_2015)

# REPOINTED 7 Sep 2026: real Butler & Butler (2011) maxima, empirically
# calibrated against the IPSA 2012-2016 overlap (see 41m_staffing_calibrate_
# butler.R), replacing the old flat-85%-assumption placeholder. Headline spec
# = mean overlap ratio (0.854); min/max specs (0.769/0.910) are in the same
# output file for robustness. 1991 has no source figure (confirmed genuine
# gap in Butler & Butler, not cropped) and is dropped here so the step
# function below carries 1990's value forward to 1992, same as it already
# does across every other multi-year gap in this series.
pre10 <- read_csv(file.path(PROJECT, "data/processed/staffing_pre2010_calibrated_butler.csv"),
                  show_col_types = FALSE) |>
  filter(!is.na(real_2015_mean)) |>
  select(cal_year = year, staffing_real = real_2015_mean)

staffing_obs <- bind_rows(pre10, ipsa) |>
  arrange(cal_year) |>
  filter(cal_year <= 2025)

# Step function: most recent staffing observation ≤ year
staffing_annual <- tibble(year = YEARS) |>
  mutate(
    obs_yr       = sapply(year, function(y)
      max(staffing_obs$cal_year[staffing_obs$cal_year <= y], na.rm = TRUE)),
    staffing_real = staffing_obs$staffing_real[match(obs_yr, staffing_obs$cal_year)]
  )

cat("\nStaffing series (sample):\n")
print(staffing_annual |> filter(year %in% c(1979, 1983, 2000, 2010, 2012, 2020, 2023)))

# ============================================================
# 4. COMBINE, NORMALISE, PCA
# ============================================================
norm01 <- function(x) (x - min(x, na.rm = TRUE)) / (max(x, na.rm = TRUE) - min(x, na.rm = TRUE))

d <- tibble(year = YEARS) |>
  left_join(career_annual  |> select(year, career_pct, career_src), by = "year") |>
  left_join(spads_annual   |> select(year, n_spads),                 by = "year") |>
  left_join(staffing_annual |> select(year, staffing_real),          by = "year") |>
  mutate(
    career_norm   = norm01(career_pct),
    spads_norm    = norm01(n_spads),
    staffing_norm = norm01(staffing_real)
  )

# Correlation matrix
cat("\n=== CORRELATION MATRIX (normalised) ===\n")
cor_mat <- cor(d[, c("career_norm", "spads_norm", "staffing_norm")], use = "complete.obs")
print(round(cor_mat, 3))

# PCA
pca_mat  <- d |> select(career_norm, spads_norm, staffing_norm) |> as.matrix()
pca_res  <- prcomp(pca_mat, scale. = TRUE, center = TRUE)
pca_summ <- summary(pca_res)

cat("\n=== PCA SUMMARY ===\n")
print(pca_summ)
cat("\nLoadings (rotation):\n")
print(round(pca_res$rotation, 3))

# PC1 scores
d <- d |>
  mutate(
    pc1    = pca_res$x[, 1],
    t      = year - min(year)
  )

pc1_var_pct <- round(pca_summ$importance[2, 1] * 100, 1)
cat(sprintf("\nPC1 explains %.1f%% of variance\n", pc1_var_pct))
cat(sprintf("Loadings: career=%.3f, spads=%.3f, staffing=%.3f\n",
            pca_res$rotation[1,1], pca_res$rotation[2,1], pca_res$rotation[3,1]))

# ============================================================
# 5. CHOW ON PC1
# ============================================================
n_chow <- nrow(d)
p_reg  <- 1   # intercept only in each segment (or intercept + slope)
p_reg2 <- 2

mod_r  <- lm(pc1 ~ t, data = d)
RSS_r  <- sum(resid(mod_r)^2)

years_sorted     <- sort(d$year)
candidate_breaks <- years_sorted[3:(length(years_sorted) - 3)]

chow_results <- do.call(rbind, lapply(candidate_breaks, function(k) {
  dat1 <- d |> filter(year <= k)
  dat2 <- d |> filter(year >  k)
  if (nrow(dat1) < 3 || nrow(dat2) < 3) return(NULL)
  rss1 <- tryCatch(sum(resid(lm(pc1 ~ t, data = dat1))^2), error = function(e) NA)
  rss2 <- tryCatch(sum(resid(lm(pc1 ~ t, data = dat2))^2), error = function(e) NA)
  if (is.na(rss1) || is.na(rss2)) return(NULL)
  RSS_u  <- rss1 + rss2
  F_stat <- ((RSS_r - RSS_u) / p_reg2) / (RSS_u / (n_chow - 2 * p_reg2 - 1))
  data.frame(break_year = k, F_stat = max(F_stat, 0))
}))

F_crit     <- qf(0.95, df1 = p_reg2, df2 = n_chow - 2 * p_reg2 - 1)
best_break <- chow_results$break_year[which.max(chow_results$F_stat)]
best_F     <- max(chow_results$F_stat)

cat(sprintf("\nChow on PC1: N=%d, critical F(%d,%d)=%.2f\n",
            n_chow, p_reg2, n_chow - 2*p_reg2 - 1, F_crit))
cat(sprintf("Data-preferred break: %d (F=%.2f)\n", best_break, best_F))
cat("\nTop 10 candidate breaks:\n")
print(chow_results |> arrange(desc(F_stat)) |> head(10))

