# Correlation labels for annotation in Panel A
r_cs <- round(cor_mat["career_norm",   "spads_norm"],    2)
r_cf <- round(cor_mat["career_norm",   "staffing_norm"], 2)
r_sf <- round(cor_mat["spads_norm",    "staffing_norm"], 2)

cor_label <- sprintf(
  "Pairwise r:  career × SPADs = %.2f\n             career × staffing = %.2f\n             SPADs × staffing = %.2f",
  r_cs, r_cf, r_sf
)

long_d <- d |>
