    "career_norm"   = "Career politicians %",
    "spads_norm"    = "SPADs in post",
    "staffing_norm" = "MP staffing spend (real)"
  ))

# --- Panel A: three normalised series ---
p_components <- ggplot(long_d, aes(x = year, y = value, colour = component,
                                    linetype = component)) +
