# — Does the self-regarding speech series covary with the index?
# — Coverage: 1979-2025 (Evan Odell + ParlSpeech V2 + official Hansard API,
#   see 64d/64e/64f); overlap with the professionalisation index (1979-2023)
#   is now 45 years, up from 32 (1988-2019 previously)
# ============================================================
SPEECH_IN <- file.path(PROJECT, "data/processed/speech_self_regarding_1979_2025.csv")

if (file.exists(SPEECH_IN)) {
  speech <- read_csv(SPEECH_IN, show_col_types = FALSE) |>
