  cat("\n=== SPEECH SERIES COVARIANCE CHECK (N=45, 1979-2023) ===\n")
  cat("Mean self-regarding ratio by period:\n")
  d_speech |>
    mutate(period = case_when(
      year <= 1988 ~ "1979-88 (Thatcher/Major-early)",
