          "Self-regarding speech = career/position references as share of career+policy hits ",
          "(1979-88 Evan Odell, 1989-2019 ParlSpeech V2, 2020-23 official Hansard API).\n",
          "Correlation, full overlap: r = %.3f."
        ),
        cor_speech["speech_norm", "pc1"]
      ),
      x = NULL, y = "Standardised score (Z)"
    ) +
    theme_bw(base_size = 11) +
    theme(
      plot.title       = element_text(face = "bold", colour = NAVY, size = 11),
      plot.subtitle    = element_text(colour = "#888888", size = 7.5, lineheight = 1.3),
      panel.grid.minor = element_blank(),
      panel.grid.major.x = element_blank(),
      axis.text.x      = element_text(angle = 45, hjust = 1),
      legend.position  = c(0.08, 0.82),
      legend.background = element_rect(fill = "white", colour = "#cccccc", linewidth = 0.3),
      legend.text      = element_text(size = 8.5),
      legend.key.width = unit(1.2, "cm")
    )

  ggsave(OVERLAY_OUT, p_overlay, width = 10, height = 6.5, dpi = 300)
  cat("Overlay figure saved:", OVERLAY_OUT, "\n")

} else {
  cat("\nSpeech data not found — run 64b_hansard_annual.R first.\n")
}
